module ActiveSupport;class Deprecation;class Deprecators;def initialize;@options={};@deprecators={};end;def [](name)@deprecators[name];end;def []=(name,deprecator)apply_options(deprecator);@deprecators[name]=deprecator;end;def each(&block)return to_enum(__method__) unless block;@deprecators.each_value(&block);end;def silenced=(silenced)set_option(:silenced,silenced);end;def debug=(debug)set_option(:debug,debug);end;def behavior=(behavior)set_option(:behavior,behavior);end;def disallowed_behavior=(disallowed_behavior)set_option(:disallowed_behavior,disallowed_behavior);end;def disallowed_warnings=(disallowed_warnings)set_option(:disallowed_warnings,disallowed_warnings);end;def silence(&block)each{|deprecator|deprecator.begin_silence};block.call;ensure each{|deprecator|deprecator.end_silence};end;private;def set_option(name,value)@options[name]=value;each{|deprecator|deprecator.public_send("#{name}=",value)};end;def apply_options(deprecator)@options.each do |name,value|deprecator.public_send("#{name}=",value);end;end;end;end;end
